// weapon.js —— 玩家武器系统
// 职责：管理当前武器、射击（射线检测命中敌人/墙）、换弹、武器切换、
//        后坐力、弹道散布、第一人称枪模、弹孔/枪口火光等视觉反馈
// 射击命中判定：从相机发出带散布的射线，与敌人胶囊体（球+圆柱近似）求最近交点，
//                并与地图 AABB 比较——若墙更近则被墙挡住。
// 经典脚本（非 ES Module）：THREE / CONFIG 由前置脚本挂到 window 提供

class WeaponSystem {
  constructor(scene, camera, player, gameMap, enemies, hud, audio) {
    this.scene = scene;
    this.camera = camera;
    this.player = player;
    this.map = gameMap;
    this.enemies = enemies;     // 引用数组（动态）
    this.hud = hud;
    this.audio = audio;

    // 当前武器
    this.currentId = 'usp';
    this.state = this._freshState('usp');

    // 输入
    this.firing = false;        // 鼠标按下持续射击
    this.fireCooldown = 0;
    this.reloadTimer = 0;
    this.switching = false;
    this._switchAnim = 0;       // 切枪动画进度 0→1
    this._spreadCurrent = 0;    // 连发散布累积值
    this._scopeZoomed = false;  // 瞄准镜放大状态（KeyC 切换）
    this._semiPending = false;
    this._firePointerId = null; // FIRE 按住拖动转视角时的指针 id（真机流畅化）
    this._bindInput();

    // 第一人称枪模
    this._buildViewModel();
    // 初始武器为 USP：隐藏 AWP 专属开镜按钮（只有 AWP 有 fov 才显示）
    const scopeBtn0 = document.getElementById('btnScope');
    if (scopeBtn0) scopeBtn0.classList.add('hidden');
    // 弹道轨迹池（临时线段）
    this._tracers = [];
    this._impacts = [];         // 弹孔
    this._buildImpactPool();
    // 高精度命中：复用单条 Raycaster（三角级精确求交）
    this.raycaster = new THREE.Raycaster();
    this._buildHitPool();
    // 枪口火光
    this._muzzleTimer = 0;
  }

  _freshState(id) {
    const w = CONFIG.weapons[id];
    return {
      id,
      mag: w.magSize,
      reserve: w.reserve,
    };
  }

  _bindInput() {
    this._onMouseDown = (e) => {
      if (e.button === 0) this.firing = true;
    };
    this._onMouseUp = (e) => {
      if (e.button === 0) this.firing = false;
    };
    this._onKeyDown = (e) => {
      if (e.code === 'KeyR') this.startReload();
      if (e.code === 'Digit1') this.switchTo('usp');
      if (e.code === 'Digit2') this.switchTo('ak47');
      if (e.code === 'Digit3') this.switchTo('awp');
      if (e.code === 'KeyC') this._toggleScopeZoom();
    };
    // 触屏设备：原生 mouse 事件会由"点击屏幕视角区"合成触发导致误开火，
    // 因此只保留键盘；射击统一走 FIRE 按钮的 setFiring()
    const isTouch = ('ontouchstart' in window) || navigator.maxTouchPoints > 0;
    if (!isTouch) {
      window.addEventListener('mousedown', this._onMouseDown);
      window.addEventListener('mouseup', this._onMouseUp);
    }
    window.addEventListener('keydown', this._onKeyDown);
  }

  // 触屏 FIRE 按钮 / 外部直接控制持续射击状态（自动武器）
  setFiring(v) {
    this.firing = v;
  }

  switchTo(id) {
    if (id === this.currentId) return;
    if (!CONFIG.weapons[id]) return;
    const w = CONFIG.weapons[id];
    // 保留每种武器的弹匣状态
    if (!this._stash) this._stash = {};
    this._stash[this.currentId] = { ...this.state };
    this.currentId = id;
    this.state = this._stash[id] ? { ...this._stash[id] } : this._freshState(id);
    this.reloadTimer = 0;
    this._semiPending = false;               // 修 H-10：清半自动挂起，防止切枪后意外开火
    this.fireCooldown = w.switchTime || 0.3; // 切枪冷却 = config switchTime（数据驱动）
    this.firing = false;
    // 切枪动画状态机（F5）：下放→上抬
    this._switchAnim = 0;
    this.switching = true;
    // 切枪音（F6）
    if (this.audio) this.audio.switch(id);
    this.hud.updateWeapon(w, this.state);
    this.hud.toast(w.name);
    // 切枪时重置 FOV 到默认 75°，scope zoom 关闭（由 KeyC 单独切换）
    if (this.camera) {
      this.camera.fov = 75;
      this.camera.updateProjectionMatrix();
    }
    this._scopeZoomed = false;
    // 关镜：隐藏瞄准镜画面，恢复普通准星
    const ov = document.getElementById('scopeOverlay');
    const ch = document.getElementById('crosshair');
    if (ov) ov.classList.add('hidden');
    if (ch) ch.classList.remove('hidden');
    // 只有 AWP（有 fov 的武器）显示「镜」开镜按钮，USP/AK 隐藏
    const scopeBtn = document.getElementById('btnScope');
    if (scopeBtn) scopeBtn.classList.toggle('hidden', !w.fov);
  }

  // 切换瞄准镜放大/正常（仅对带 fov 的武器如 AWP 生效）
  // 公共方法：键盘 KeyC 与触屏"镜"按钮共用
  toggleScopeZoom() {
    const w = CONFIG.weapons[this.currentId];
    if (!w.fov || !this.camera) return;   // 非狙击武器无放大
    this._scopeZoomed = !this._scopeZoomed;
    this.camera.fov = this._scopeZoomed ? w.fov : 75;
    this.camera.updateProjectionMatrix();
    // 瞄准镜画面：开镜显示镜筒+十字线并隐藏普通准星，关镜恢复
    const ov = document.getElementById('scopeOverlay');
    const ch = document.getElementById('crosshair');
    if (ov) ov.classList.toggle('hidden', !this._scopeZoomed);
    if (ch) ch.classList.toggle('hidden', this._scopeZoomed);
    if (this.hud) this.hud.toast(this._scopeZoomed ? '开镜' : '关镜');
  }
  _toggleScopeZoom() { this.toggleScopeZoom(); }

  startReload() {
    const w = CONFIG.weapons[this.currentId];
    if (this.reloadTimer > 0) return;
    if (this.state.mag >= w.magSize) return;
    if (this.state.reserve <= 0) {
      // 备弹为 0：差异化提示（M-9）
      this.hud.toast('备弹耗尽！');
      return;
    }
    this.reloadTimer = w.reloadTime;
    // 换弹音效接入（D1）
    if (this.audio) this.audio.reload();
    this.hud.toast('换弹中…');
  }

  _finishReload() {
    const w = CONFIG.weapons[this.currentId];
    const need = w.magSize - this.state.mag;
    const take = Math.min(need, this.state.reserve);
    this.state.mag += take;
    this.state.reserve -= take;
    this.hud.updateWeapon(w, this.state);
  }

  // 弹药包补给：当前枪与已暂存过的枪都补，各自封顶在初始储备（reserve）
  // 返回 { added, parts }：added=是否有任何补到，parts=['USP +12', ...] 供提示
  addAmmo(refill) {
    const parts = [];
    for (const id of Object.keys(refill)) {
      const w = CONFIG.weapons[id];
      if (!w) continue;
      let before, after;
      if (id === this.currentId) {
        before = this.state.reserve;
        after = Math.min(w.reserve, before + refill[id]);
        if (after > before) {
          this.state.reserve = after;
          this.hud.updateWeapon(w, this.state);
        }
      } else if (this._stash && this._stash[id]) {
        before = this._stash[id].reserve;
        after = Math.min(w.reserve, before + refill[id]);
        if (after > before) this._stash[id].reserve = after;
      } else {
        continue;   // 从未切过的枪储备仍是初始满值，无可补
      }
      if (after > before) parts.push(`${w.name} +${after - before}`);
    }
    return { added: parts.length > 0, parts };
  }

  // ---------- 主更新 ----------
  update(dt) {
    const w = CONFIG.weapons[this.currentId];

    // 换弹
    if (this.reloadTimer > 0) {
      this.reloadTimer -= dt;
      if (this.reloadTimer <= 0) this._finishReload();
    }

    // 射击冷却
    if (this.fireCooldown > 0) this.fireCooldown -= dt;

    // 连发散布：未开火时按 spreadDecay 恢复（P1 S1）
    if (this._spreadCurrent > 0) {
      this._spreadCurrent = Math.max(w.spread, this._spreadCurrent - w.spreadDecay * dt);
    }

    // 持续射击（自动武器）
    const wantFire = this.firing && w.type === 'auto';
    const wantFireSemi = this._semiPending;
    if ((wantFire || wantFireSemi) && this.fireCooldown <= 0 && this.reloadTimer <= 0 && !this.switching) {
      this._fire();
      this._semiPending = false;
    }

    // 准星扩散与当前散布联动（静止收拢、移动张开 + 连发累积，所见即所射）
    const hSpeed = Math.hypot(this.player.velocity.x, this.player.velocity.z);
    const moveFactor = Math.min(1, hSpeed / CONFIG.player.walkSpeed);
    const curSpread = (this._spreadCurrent || w.spread) + w.spreadMove * moveFactor;
    this.hud.setCrosshairSpread(curSpread);

    // 枪模动画
    this._updateViewModel(dt);

    // 弹道/弹孔淡出
    this._updateTracers(dt);

    // 枪口火光衰减（作用于当前武器）
    if (this._muzzleTimer > 0) {
      this._muzzleTimer -= dt;
      const gun = this._viewGuns && this._viewGuns[this.currentId];
      const flash = gun && gun.userData.flash;
      if (flash) flash.material.opacity = Math.max(0, this._muzzleTimer / 0.04);
    }
  }

  // 切枪动画状态机（F5）：下放（0-0.5）→ 上抬（0.5-1），时长 config.switchTime
  // 在 _updateViewModel 内推进并应用（避免跨函数引用 bob）
  _updateSwitchAnim(dt) {
    if (!this.switching) return null;
    const w = CONFIG.weapons[this.currentId];
    const st = w.switchTime || 0.3;
    this._switchAnim += dt / st;
    if (this._switchAnim >= 1) {
      this._switchAnim = 1;
      this.switching = false;
    }
    const t = this._switchAnim;
    // 下放段 t<0.5：枪下降 + 前倾；上抬段 t>0.5：回位
    const down = t < 0.5 ? t / 0.5 : 1 - (t - 0.5) / 0.5;   // 0→1→0
    return { y: -down * 0.30, r: -down * 0.55 };
  }

  // 半自动：鼠标按下触发一次（冷却/换弹/切枪中忽略，防幽灵子弹 M-8）
  triggerSemi() {
    const w = CONFIG.weapons[this.currentId];
    if (w.type !== 'semi') return;
    if (this.fireCooldown > 0 || this.reloadTimer > 0 || this.switching) return;
    this._semiPending = true;
  }

  _fire() {
    const w = CONFIG.weapons[this.currentId];
    if (this.state.mag <= 0) {
      // 空仓（D2）：咔嗒音 + 红字告警 + 备弹 0 差异化文案
      if (this.audio) this.audio.dryFire();
      this.hud.setAmmoWarning('empty');
      this.fireCooldown = 0.2;
      this.firing = false;
      if (w.autoReload) this.startReload();
      return;
    }
    this.state.mag--;
    this.fireCooldown = w.fireRate;
    this.hud.updateWeapon(w, this.state);
    this.hud.crosshairFire();

    // 连发散布累积（P1 S1）：AK 每发 +spreadInc，USP 不累积
    if (w.spreadInc > 0) {
      this._spreadCurrent = Math.min(w.spreadMax, (this._spreadCurrent || w.spread) + w.spreadInc);
    }

    // 计算弹道方向（带散布）
    const ray = this.player.getAimRay();
    // 移动时散布更大（叠加连发累积值）
    const hSpeed = Math.hypot(this.player.velocity.x, this.player.velocity.z);
    const moveFactor = Math.min(1, hSpeed / CONFIG.player.walkSpeed);
    const spread = (this._spreadCurrent || w.spread) + w.spreadMove * moveFactor;
    const dir = ray.direction.clone();
    // 在"屏幕平面"内做圆盘均匀采样（用相机右/上向量做基），
    // 保证弹孔分布始终落在准星扩散范围内，且朝向任意角度都不会畸变
    if (spread > 0) {
      const right = new THREE.Vector3(1, 0, 0).applyQuaternion(this.camera.quaternion);
      const up = new THREE.Vector3(0, 1, 0).applyQuaternion(this.camera.quaternion);
      const ang = Math.random() * Math.PI * 2;
      const rad = spread * Math.sqrt(Math.random());
      dir.addScaledVector(right, Math.cos(ang) * rad)
         .addScaledVector(up, Math.sin(ang) * rad)
         .normalize();
    }

    const origin = ray.origin.clone();

    // 后坐力
    this.player.applyRecoil(w.recoil);

    // ---- 高精度命中：Three.js Raycaster 对敌人真实网格做三角级求交 ----
    const hit = this._hitscan(origin, dir, w.range);
    // 墙遮挡：地图 AABB 精确求交（含命中面法线，用于弹孔贴墙）
    const wall = this.map.raycastDetailed(origin, dir, w.range);

    // 视觉：弹道轨迹终点（取最近命中点：敌人 / 墙 / 最大射程）
    let endT = w.range;
    if (hit && hit.t < endT) endT = hit.t;
    if (wall.t < endT) endT = wall.t;
    const endPoint = origin.clone().addScaledVector(dir, endT);
    this._spawnTracer(origin, endPoint);
    this._spawnMuzzleFlash();

    // 命中处理
    if (hit && hit.t < wall.t) {
      const dmg = this._damageForPart(w, hit.part, hit.t);   // 部位倍率 × 距离衰减（F7/F8）
      const killed = hit.enemy.takeDamage(dmg, hit.part);
      const isHead = hit.part === 'head';
      // 视觉：命中标记三态（F1-F3）+ 伤害飘字（N4）
      this.hud.hitMarker(isHead, killed);
      const sp = this.hud.worldToScreen(hit.point, this.camera);
      this.hud.showDamageNumber(dmg, sp.x, sp.y, isHead);
      this._spawnHitSpark(hit.point, hit.normal, hit.part);
      // 音效：命中/爆头/击杀（H-7 修复：由 weapon 统一发起）
      if (this.audio) this.audio.hit(isHead, killed);
      if (killed) this.hud.killFeed(hit.enemy.name, w.name, isHead);
    } else if (wall.t < w.range) {
      // 击中墙体，按墙面法线贴弹孔（精确贴合墙面）+ 墙击音
      this._spawnImpact(endPoint, wall.normal || dir.clone().negate());
      if (this.audio) this.audio.wallHit('concrete');
    }

    // 音效
    if (this.audio) this.audio.shot(this.currentId);
  }

  // 高精度命中：对全部存活敌人网格做三角级射线求交，返回最近命中
  // { enemy, part, t, point, normal } 或 null
  _hitscan(origin, dir, range) {
    const targets = [];
    for (const en of this.enemies) {
      if (!en.alive) continue;
      // 敌人本帧刚移动过，强制刷新世界矩阵，保证命中与渲染位置一致
      en.mesh.updateMatrixWorld(true);
      for (const m of en.hitMeshes) targets.push(m);
    }
    if (targets.length === 0) return null;

    this.raycaster.set(origin, dir);
    this.raycaster.near = 0.001;
    this.raycaster.far = range;
    const hits = this.raycaster.intersectObjects(targets, false);
    if (hits.length === 0) return null;

    // intersectObjects 已按距离升序排序，取最近者
    const h = hits[0];
    const obj = h.object;
    // 面法线从局部空间变换到世界空间（用于精确着弹点特效）
    const normal = h.face
      ? h.face.normal.clone().transformDirection(obj.matrixWorld).normalize()
      : dir.clone().negate();
    return {
      enemy: obj.userData.enemy,
      part: obj.userData.part || 'torso',
      t: h.distance,
      point: h.point.clone(),
      normal,
    };
  }

  // 部位 → 伤害倍率（head/torso/arm/leg/gun）× 距离衰减（F7）
  // 距离衰减：<=falloffStart 满伤；>=falloffEnd falloffMin；中间线性
  _damageForPart(w, part, dist) {
    let dmg;
    switch (part) {
      case 'head': dmg = w.damage * w.headMult;
        break;
      case 'leg':  dmg = w.damage * w.legMult;
        break;
      case 'arm':  dmg = w.damage * (w.armMult ?? 1);
        break;
      case 'gun':  dmg = w.damage * (w.gunMult ?? 0.5);
        break;
      default:     dmg = w.damage;   // torso / body
    }
    // 距离衰减（config falloffStart/End/Min，未配置则满伤）
    if (w.falloffStart && w.falloffEnd && dist !== undefined) {
      if (dist <= w.falloffStart) return Math.round(dmg);
      if (dist >= w.falloffEnd) return Math.round(dmg * (w.falloffMin ?? 0.5));
      const t = (dist - w.falloffStart) / (w.falloffEnd - w.falloffStart);
      return Math.round(dmg * (1 - (1 - (w.falloffMin ?? 0.5)) * t));
    }
    return Math.round(dmg);
  }

  // 着弹点特效池（命中敌人时在精确命中点闪出血花/爆头火花）
  _buildHitPool() {
    this._hitPool = [];
    const mat = new THREE.SpriteMaterial({
      color: 0xff2a2a, transparent: true, opacity: 0.95,
    });
    for (let i = 0; i < 30; i++) {
      const s = new THREE.Sprite(mat.clone());
      s.scale.setScalar(0.14);
      s.visible = false;
      this.scene.add(s);
      this._hitPool.push(s);
    }
    this._hitSparks = [];
  }

  _spawnHitSpark(point, normal, part) {
    let s = this._hitPool.pop();
    if (!s) return;
    s.position.copy(point).addScaledVector(normal, 0.02);
    s.material.color.setHex(part === 'head' ? 0xffe14d : 0xff2a2a);
    s.scale.setScalar(part === 'head' ? 0.22 : 0.14);
    s.visible = true;
    s.material.opacity = 0.95;
    s.userData.life = 0.12;
    this.scene.add(s);
    this._hitSparks.push(s);
  }

  // ---------- 视觉：第一人称枪模（高精度程序化贴图版） ----------
  _buildViewModel() {
    this._viewGroup = new THREE.Group();
    this.camera.add(this._viewGroup);
    this.scene.add(this.camera);   // 确保 camera 加入场景，枪模跟随

    // 贴图：先用程序化贴图兜底，再异步加载用户上传/联网下载的真实贴图替换（避免加载瞬间黑帧）
    const texUsp = this._makeMetalTexture();   // USP 程序化兜底（金属灰），加载后被用户上传的 usp 贴图替换
    const texWood = this._makeWoodTexture();

    // USP 材质（3D 卡通黑色金属 + 环境反射 + clearcoat，贴图采用用户上传的 usp.png）
    const uspMat = new THREE.MeshPhysicalMaterial({ map: texUsp, roughness: 0.32, metalness: 0.95, clearcoat: 0.3, clearcoatRoughness: 0.25 });
    const uspDarkMat = new THREE.MeshPhysicalMaterial({ map: texUsp, color: 0x808080, roughness: 0.42, metalness: 0.9, clearcoat: 0.2, clearcoatRoughness: 0.3 });
    const uspGripMat = new THREE.MeshPhysicalMaterial({ map: texUsp, roughness: 0.6, metalness: 0.8, clearcoat: 0.15, clearcoatRoughness: 0.35 });
    const woodMat = new THREE.MeshStandardMaterial({ map: texWood, roughness: 0.7, metalness: 0.02 });

    // AK 卡通配色（采样自用户三视图：军绿 #565C46 / 暖木 #B98A4A）
    // 仍用 MeshPhysicalMaterial + clearcoat + IBL 环境反射——卡通配色 ≠ 2D 平面化，3D 质感保留
    // AK 贴图：直接用程序化生成的暖青铜军绿 diffuse（之前的用户上传图是 UV 展开图，
    // 有大量透明区，会"透出底色+贴图错位"，不再用）
    const texAk47 = this._makeAk47Texture();
    // AK 材质（3D 卡通金属 + 环境反射 + clearcoat，贴图为程序化暖青铜军绿 diffuse）
    const akAk47Mat = new THREE.MeshPhysicalMaterial({ map: texAk47, roughness: 0.42, metalness: 0.85, clearcoat: 0.22, clearcoatRoughness: 0.32 });
    const akAk47WarmMat = new THREE.MeshPhysicalMaterial({ map: texAk47, roughness: 0.40, metalness: 0.87, clearcoat: 0.25, clearcoatRoughness: 0.30 });
    const akAk47DarkMat = new THREE.MeshPhysicalMaterial({ map: texAk47, color: 0x8a8e82, roughness: 0.48, metalness: 0.80, clearcoat: 0.18, clearcoatRoughness: 0.38 });

    // USP 使用用户上传的 usp 贴图覆盖程序化兜底（加载完成前用纯色兜底避免黑帧）
    this._applyTex(window.TEX && window.TEX.usp, [uspMat, uspDarkMat, uspGripMat]);
    // AK 不再加载外部贴图（之前用用户上传的 UV 展开图有严重错乱），改用程序化暖木纹/深橄榄金属 diffuse 严格匹配用户 3D 渲染图主色

    // 两把枪各自独立的高精度模型，切换时显隐
    this._viewGuns = {
      usp: this._buildUSP(uspMat, uspDarkMat, uspGripMat),
      ak47: this._buildAK(akAk47WarmMat, woodMat, akAk47Mat, akAk47DarkMat),
      awp: this._buildAwp(akAk47WarmMat, woodMat, akAk47Mat, akAk47DarkMat),
    };
    this._viewGroup.add(this._viewGuns.usp);
    this._viewGroup.add(this._viewGuns.ak47);
    this._viewGroup.add(this._viewGuns.awp);

    // 当前枪模姿态
    this._viewRecoil = 0;
  }

  // 真实贴图加载完成后替换材质贴图（离线 base64，无 CORS 问题）
  _applyTex(url, mats) {
    if (!url) return;
    new THREE.TextureLoader().load(url, (tex) => {
      tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
      if ('SRGBColorSpace' in THREE) tex.colorSpace = THREE.SRGBColorSpace;
      for (const m of mats) { m.map = tex; m.needsUpdate = true; }
    });
  }

  // ---- 程序化贴图 ----

  // 拉丝枪金属（深灰 + 竖向细纹 + 顶部高光 + 面板分割线）
  _makeMetalTexture() {
    const c = document.createElement('canvas');
    c.width = 256; c.height = 256;
    const g = c.getContext('2d');
    g.fillStyle = '#2b2d33';
    g.fillRect(0, 0, 256, 256);
    for (let i = 0; i < 256; i++) {
      const v = 34 + Math.random() * 40;
      g.fillStyle = `rgba(${v},${v + 2},${v + 6},0.06)`;
      g.fillRect(i, 0, 1, 256);
    }
    const grad = g.createLinearGradient(0, 0, 0, 256);
    grad.addColorStop(0, 'rgba(255,255,255,0.12)');
    grad.addColorStop(0.45, 'rgba(255,255,255,0)');
    grad.addColorStop(1, 'rgba(0,0,0,0.22)');
    g.fillStyle = grad;
    g.fillRect(0, 0, 256, 256);
    g.strokeStyle = 'rgba(0,0,0,0.45)';
    g.lineWidth = 2;
    for (let y = 64; y < 256; y += 70) {
      g.beginPath(); g.moveTo(0, y); g.lineTo(256, y); g.stroke();
    }
    return new THREE.CanvasTexture(c);
  }

  // 卡通暖木（采样自三视图 #B98A4A：大色块 + 顶部高光带 + 底部阴影带 + 粗木纹 + 描边线）
  // 仅 AK 使用（USP 不用木件），卡通渲染风格：色块为主、纹理为辅
  // 注：贴图主色比三视图采样色深约 30%（场景环境光 1.8 + IBL 会提亮，预补偿防过曝）
  _makeWoodTexture() {
    const c = document.createElement('canvas');
    c.width = 256; c.height = 256;
    const g = c.getContext('2d');
    // 主色块（SRGB 色彩空间下会略暗，主色取采样值的 90%：目标观感 #b98a4a）
    // 木纹贴图：基色按用户上传 3D 渲染图主色 #A07020（暖木），非之前的 #96713c 深棕
    g.fillStyle = '#A07020';
    g.fillRect(0, 0, 256, 256);
    // 顶部高光带（卡通风：亮部窄而明显）
    const hi = g.createLinearGradient(0, 0, 0, 110);
    hi.addColorStop(0, 'rgba(220,160,80,0.8)');
    hi.addColorStop(0.7, 'rgba(220,160,80,0.12)');
    hi.addColorStop(1, 'rgba(220,160,80,0)');
    g.fillStyle = hi;
    g.fillRect(0, 0, 256, 110);
    // 底部阴影带
    const sh = g.createLinearGradient(0, 170, 0, 256);
    sh.addColorStop(0, 'rgba(120,80,30,0)');
    sh.addColorStop(0.5, 'rgba(120,80,30,0.35)');
    sh.addColorStop(1, 'rgba(80,50,15,0.8)');
    g.fillStyle = sh;
    g.fillRect(0, 170, 256, 86);
    // 粗木纹（2~3 条大波浪，卡通感而非照片感）
    g.strokeStyle = 'rgba(100,70,25,0.55)';
    g.lineWidth = 3;
    for (const y0 of [70, 130, 195]) {
      g.beginPath();
      for (let x = 0; x <= 256; x += 16) {
        const yy = y0 + Math.sin(x * 0.05 + y0) * 6;
        if (x === 0) g.moveTo(x, yy); else g.lineTo(x, yy);
      }
      g.stroke();
    }
    // 细亮纹（高光侧的反光纹）
    g.strokeStyle = 'rgba(230,180,120,0.4)';
    g.lineWidth = 1.5;
    for (const y0 of [96, 160]) {
      g.beginPath();
      for (let x = 0; x <= 256; x += 16) {
        const yy = y0 + Math.sin(x * 0.05 + y0 * 1.3) * 5;
        if (x === 0) g.moveTo(x, yy); else g.lineTo(x, yy);
      }
      g.stroke();
    }
    // 上下描边（卡通轮廓感）
    g.strokeStyle = 'rgba(50,35,15,0.6)';
    g.lineWidth = 3;
    g.beginPath(); g.moveTo(0, 1.5); g.lineTo(256, 1.5); g.stroke();
    g.beginPath(); g.moveTo(0, 254.5); g.lineTo(256, 254.5); g.stroke();
    const woodTex = new THREE.CanvasTexture(c);
    if ('SRGBColorSpace' in THREE) woodTex.colorSpace = THREE.SRGBColorSpace;   // 照片级贴图色彩才正确（防线性空间提亮）
    return woodTex;
  }

  // 卡通军绿金属（采样自三视图 #565C46：色块 + 顶部亮带 + 底部暗带 + 面板分割描边 + 细颗粒）
  // 用于 AK 机匣/枪管/弹匣等金属件；保持金属反射（metalness 高），配色走卡通
  // 注：贴图主色比三视图采样色深约 30%（环境光 + IBL 提亮预补偿）
  _makeArmyMetalTexture() {
    const c = document.createElement('canvas');
    c.width = 256; c.height = 256;
    const g = c.getContext('2d');
    // 主色块（SRGB 下取采样值 90%：目标观感 #565c46）
    g.fillStyle = '#484e3c';
    g.fillRect(0, 0, 256, 256);
    // 顶部高光带（卡通硬高光）
    const hi = g.createLinearGradient(0, 0, 0, 90);
    hi.addColorStop(0, 'rgba(94,100,78,0.9)');
    hi.addColorStop(0.65, 'rgba(88,94,74,0.25)');
    hi.addColorStop(1, 'rgba(88,94,74,0)');
    g.fillStyle = hi;
    g.fillRect(0, 0, 256, 90);
    // 底部阴影带
    const sh = g.createLinearGradient(0, 180, 0, 256);
    sh.addColorStop(0, 'rgba(38,42,32,0)');
    sh.addColorStop(0.55, 'rgba(38,42,32,0.4)');
    sh.addColorStop(1, 'rgba(26,30,22,0.85)');
    g.fillStyle = sh;
    g.fillRect(0, 180, 256, 76);
    // 细颗粒噪点（金属质感，弱强度保持卡通色块感）
    for (let i = 0; i < 900; i++) {
      const x = Math.random() * 256, y = Math.random() * 256;
      const v = Math.random();
      g.fillStyle = v > 0.5 ? 'rgba(108,114,90,0.05)' : 'rgba(20,24,16,0.05)';
      g.fillRect(x, y, 1.5, 1.5);
    }
    // 面板分割描边（AK 机匣的铆接/分件感，深色细线）
    g.strokeStyle = 'rgba(22,26,18,0.65)';
    g.lineWidth = 2;
    for (const y of [52, 128, 208]) {
      g.beginPath(); g.moveTo(0, y); g.lineTo(256, y); g.stroke();
    }
    // 分割线旁的铆钉点（卡通小细节）
    g.fillStyle = 'rgba(18,22,14,0.75)';
    for (const y of [52, 128, 208]) {
      for (let x = 20; x < 256; x += 46) {
        g.beginPath(); g.arc(x, y - 5, 2, 0, Math.PI * 2); g.fill();
      }
    }
    // 上下边缘描边
    g.strokeStyle = 'rgba(18,22,14,0.7)';
    g.lineWidth = 3;
    g.beginPath(); g.moveTo(0, 1.5); g.lineTo(256, 1.5); g.stroke();
    g.beginPath(); g.moveTo(0, 254.5); g.lineTo(256, 254.5); g.stroke();
    const armyTex = new THREE.CanvasTexture(c);
    if ('SRGBColorSpace' in THREE) armyTex.colorSpace = THREE.SRGBColorSpace;
    return armyTex;
  }

  // 暖青铜军绿金属（贴 3D 渲染图机匣色调：#5a5e48 偏暖，金黄高光）
  _makeArmyMetalWarmTexture() {
    const c = document.createElement('canvas');
    c.width = 256; c.height = 256;
    const g = c.getContext('2d');
    // 主色块（暖青铜军绿，目标 #5a5e48）
    g.fillStyle = '#535840';
    g.fillRect(0, 0, 256, 256);
    // 顶部暖色高光带
    const hi = g.createLinearGradient(0, 0, 0, 95);
    hi.addColorStop(0, 'rgba(118,116,80,0.85)');
    hi.addColorStop(0.6, 'rgba(108,106,72,0.25)');
    hi.addColorStop(1, 'rgba(108,106,72,0)');
    g.fillStyle = hi;
    g.fillRect(0, 0, 256, 95);
    // 底部阴影
    const sh = g.createLinearGradient(0, 175, 0, 256);
    sh.addColorStop(0, 'rgba(40,42,32,0)');
    sh.addColorStop(0.55, 'rgba(40,42,32,0.4)');
    sh.addColorStop(1, 'rgba(28,30,22,0.85)');
    g.fillStyle = sh;
    g.fillRect(0, 175, 256, 81);
    // 细颗粒（暖金属感）
    for (let i = 0; i < 850; i++) {
      const x = Math.random() * 256, y = Math.random() * 256;
      const v = Math.random();
      g.fillStyle = v > 0.5 ? 'rgba(120,118,84,0.06)' : 'rgba(20,22,14,0.05)';
      g.fillRect(x, y, 1.5, 1.5);
    }
    // 面板分割描边
    g.strokeStyle = 'rgba(22,24,16,0.65)';
    g.lineWidth = 2;
    for (const y of [50, 125, 200]) {
      g.beginPath(); g.moveTo(0, y); g.lineTo(256, y); g.stroke();
    }
    // 铆钉点
    g.fillStyle = 'rgba(18,20,12,0.78)';
    for (const y of [50, 125, 200]) {
      for (let x = 20; x < 256; x += 46) {
        g.beginPath(); g.arc(x, y - 5, 2, 0, Math.PI * 2); g.fill();
      }
    }
    // 边缘描边
    g.strokeStyle = 'rgba(20,22,14,0.7)';
    g.lineWidth = 3;
    g.beginPath(); g.moveTo(0, 1.5); g.lineTo(256, 1.5); g.stroke();
    g.beginPath(); g.moveTo(0, 254.5); g.lineTo(256, 254.5); g.stroke();
    const warmTex = new THREE.CanvasTexture(c);
    if ('SRGBColorSpace' in THREE) warmTex.colorSpace = THREE.SRGBColorSpace;
    return warmTex;
  }

  // AK47 漫反射贴图（替代之前误用的 UV 展开图：那张是 UV 布局，大量透明区当 diffuse
  // 用会"透出底色+贴图错位"。改为程序化生成的暖青铜军绿 diffuse，匹配用户 3D 渲染图主色 #5a5e48）
  _makeAk47Texture() {
    const c = document.createElement('canvas');
    c.width = 512; c.height = 512;
    const g = c.getContext('2d');
    // 暖青铜军绿基色（对应用户上传 3D 渲染图主色）
    // AK 金属贴图：基色按用户上传 3D 渲染图主色 #405040（深橄榄），非之前的 #5a5e48 暖青铜
    g.fillStyle = '#405040';
    g.fillRect(0, 0, 512, 512);
    // 顶部暖色高光带（机匣顶面反光，颜色按基色调）
    const hi = g.createLinearGradient(0, 0, 0, 180);
    hi.addColorStop(0, 'rgba(110, 108, 72, 0.85)');
    hi.addColorStop(0.7, 'rgba(100, 98, 64, 0.2)');
    hi.addColorStop(1, 'rgba(100, 98, 64, 0)');
    g.fillStyle = hi;
    g.fillRect(0, 0, 512, 180);
    // 底部阴影
    const sh = g.createLinearGradient(0, 360, 0, 512);
    sh.addColorStop(0, 'rgba(36, 38, 26, 0)');
    sh.addColorStop(0.5, 'rgba(36, 38, 26, 0.4)');
    sh.addColorStop(1, 'rgba(24, 26, 16, 0.85)');
    g.fillStyle = sh;
    g.fillRect(0, 360, 512, 152);
    // 细颗粒金属感
    for (let i = 0; i < 2000; i++) {
      const x = Math.random() * 512, y = Math.random() * 512;
      g.fillStyle = Math.random() > 0.5 ? 'rgba(100, 98, 68, 0.08)' : 'rgba(16, 18, 10, 0.06)';
      g.fillRect(x, y, 1.5, 1.5);
    }
    // 面板分割描边
    g.strokeStyle = 'rgba(16, 18, 10, 0.7)';
    g.lineWidth = 3;
    for (const y of [100, 256, 410]) {
      g.beginPath(); g.moveTo(0, y); g.lineTo(512, y); g.stroke();
    }
    const tex = new THREE.CanvasTexture(c);
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
    if ('SRGBColorSpace' in THREE) tex.colorSpace = THREE.SRGBColorSpace;
    return tex;
  }

  // 防滑纹（深黑 + 密集点纹）
  _makeGripTexture() {
    const c = document.createElement('canvas');
    c.width = 256; c.height = 256;
    const g = c.getContext('2d');
    g.fillStyle = '#17171b';
    g.fillRect(0, 0, 256, 256);
    for (let y = 5; y < 256; y += 11) {
      for (let x = 5; x < 256; x += 11) {
        g.fillStyle = `rgba(${58 + Math.random() * 26},${58 + Math.random() * 26},${64 + Math.random() * 26},0.55)`;
        g.beginPath(); g.arc(x, y, 3, 0, Math.PI * 2); g.fill();
      }
    }
    return new THREE.CanvasTexture(c);
  }

  // 枪口火光网格（挂到每把枪的 userData.flash）
  _makeMuzzleFlashMesh(x, y, z) {
    const mat = new THREE.MeshBasicMaterial({
      color: 0xffcc44, transparent: true, opacity: 0, depthTest: false,
    });
    const flash = new THREE.Mesh(new THREE.SphereGeometry(0.06, 8, 8), mat);
    flash.position.set(x, y, z);
    return flash;
  }

  // USP 手枪：套筒 + 防滑槽 + 枪身 + 扳机护圈 + 照门/准星 + 击锤 + 握把
  // USP 手枪（3D 卡通版：套筒/枪身/握把用 ExtrudeGeometry 圆角轮廓，
  // 贴图采用用户上传的 usp 贴图，配 MeshPhysicalMaterial + clearcoat + IBL 环境反射）
  _buildUSP(uspMat, uspDarkMat, uspGripMat) {
    const g = new THREE.Group();
    const X = 0.22;

    // ---- 套筒（ExtrudeGeometry 圆角矩形横截面，挤出后居中）----
    const slideShape = new THREE.Shape();
    const sw = 0.05, sh = 0.055, sr = 0.015;
    slideShape.moveTo(-sw / 2 + sr, sh / 2);
    slideShape.lineTo(sw / 2 - sr, sh / 2);
    slideShape.quadraticCurveTo(sw / 2, sh / 2, sw / 2, sh / 2 - sr);
    slideShape.lineTo(sw / 2, -sh / 2 + sr);
    slideShape.quadraticCurveTo(sw / 2, -sh / 2, sw / 2 - sr, -sh / 2);
    slideShape.lineTo(-sw / 2 + sr, -sh / 2);
    slideShape.quadraticCurveTo(-sw / 2, -sh / 2, -sw / 2, -sh / 2 + sr);
    slideShape.lineTo(-sw / 2, sh / 2 - sr);
    slideShape.quadraticCurveTo(-sw / 2, sh / 2, -sw / 2 + sr, sh / 2);
    slideShape.closePath();
    const slideGeo = new THREE.ExtrudeGeometry(slideShape, { depth: 0.24, bevelEnabled: true, bevelSize: 0.003, bevelThickness: 0.003, bevelSegments: 2 });
    slideGeo.translate(0, 0, -0.12);   // 居中挤出
    const slide = new THREE.Mesh(slideGeo, uspMat);
    slide.position.set(X, -0.145, -0.52);
    slide.castShadow = true;
    g.add(slide);

    // 套筒后部防滑槽（6 条细棱，比之前更密）
    for (let i = 0; i < 6; i++) {
      const serr = new THREE.Mesh(new THREE.BoxGeometry(0.052, 0.006, 0.012), uspDarkMat);
      serr.position.set(X, -0.145, -0.42 - i * 0.014);
      g.add(serr);
    }
    // 套筒前部短棱（3D 卡通细节）
    for (let i = 0; i < 3; i++) {
      const serr = new THREE.Mesh(new THREE.BoxGeometry(0.052, 0.004, 0.008), uspDarkMat);
      serr.position.set(X, -0.14, -0.56 - i * 0.01);
      g.add(serr);
    }

    // ---- 枪身（ExtrudeGeometry 圆角，深度 0.17）----
    const frameShape = new THREE.Shape();
    const fw = 0.048, fh = 0.05, fr = 0.01;
    frameShape.moveTo(-fw / 2 + fr, fh / 2);
    frameShape.lineTo(fw / 2 - fr, fh / 2);
    frameShape.quadraticCurveTo(fw / 2, fh / 2, fw / 2, fh / 2 - fr);
    frameShape.lineTo(fw / 2, -fh / 2 + fr);
    frameShape.quadraticCurveTo(fw / 2, -fh / 2, fw / 2 - fr, -fh / 2);
    frameShape.lineTo(-fw / 2 + fr, -fh / 2);
    frameShape.quadraticCurveTo(-fw / 2, -fh / 2, -fw / 2, -fh / 2 + fr);
    frameShape.lineTo(-fw / 2, fh / 2 - fr);
    frameShape.quadraticCurveTo(-fw / 2, fh / 2, -fw / 2 + fr, fh / 2);
    frameShape.closePath();
    const frameGeo = new THREE.ExtrudeGeometry(frameShape, { depth: 0.17, bevelEnabled: true, bevelSize: 0.003, bevelThickness: 0.003, bevelSegments: 2 });
    frameGeo.translate(0, 0, -0.085);
    const frame = new THREE.Mesh(frameGeo, uspDarkMat);
    frame.position.set(X, -0.205, -0.48);
    frame.castShadow = true;
    g.add(frame);

    // ---- 握把（ExtrudeGeometry 军用手枪弧形 + 掌底膨起）----
    const gripShape = new THREE.Shape();
    gripShape.moveTo(-0.02, 0.075);
    gripShape.lineTo(0.02, 0.075);
    gripShape.lineTo(0.018, -0.02);
    gripShape.quadraticCurveTo(0.015, -0.075, 0, -0.075);
    gripShape.quadraticCurveTo(-0.015, -0.075, -0.018, -0.02);
    gripShape.lineTo(-0.02, 0.075);
    gripShape.closePath();
    const gripGeo = new THREE.ExtrudeGeometry(gripShape, { depth: 0.08, bevelEnabled: true, bevelSize: 0.005, bevelThickness: 0.005, bevelSegments: 2 });
    gripGeo.translate(0, 0, -0.04);
    const grip = new THREE.Mesh(gripGeo, uspGripMat);
    grip.position.set(X, -0.31, -0.42);
    grip.rotation.x = -0.22;
    g.add(grip);

    // ---- 扳机护圈（3 段 U 形，比单 box 更像真枪）----
    const guardLeft = new THREE.Mesh(new THREE.BoxGeometry(0.005, 0.035, 0.005), uspDarkMat);
    guardLeft.position.set(X - 0.014, -0.24, -0.5);
    g.add(guardLeft);
    const guardRight = guardLeft.clone();
    guardRight.position.x = X + 0.014;
    g.add(guardRight);
    const guardBottom = new THREE.Mesh(new THREE.BoxGeometry(0.023, 0.005, 0.005), uspDarkMat);
    guardBottom.position.set(X, -0.258, -0.5);
    g.add(guardBottom);

    // ---- 准星（前后）----
    const rearSight = new THREE.Mesh(new THREE.BoxGeometry(0.014, 0.03, 0.014), uspDarkMat);
    rearSight.position.set(X, -0.112, -0.44);
    g.add(rearSight);
    const frontSight = new THREE.Mesh(new THREE.BoxGeometry(0.012, 0.022, 0.012), uspDarkMat);
    frontSight.position.set(X, -0.112, -0.62);
    g.add(frontSight);

    // ---- 击锤（尾部）----
    const hammer = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.025, 0.02), uspDarkMat);
    hammer.position.set(X, -0.13, -0.38);
    g.add(hammer);

    // ---- 枪口（套筒前端）----
    const muzzle = new THREE.Mesh(new THREE.CylinderGeometry(0.016, 0.016, 0.02, 12), uspDarkMat);
    muzzle.rotation.x = Math.PI / 2;
    muzzle.position.set(X, -0.145, -0.645);
    g.add(muzzle);

    // ---- 扳机 ----
    const trigger = new THREE.Mesh(new THREE.BoxGeometry(0.012, 0.032, 0.012), uspDarkMat);
    trigger.position.set(X, -0.225, -0.515);
    g.add(trigger);

    // ---- 抛壳口（套筒右侧暗槽）----
    const ejector = new THREE.Mesh(new THREE.BoxGeometry(0.006, 0.02, 0.05),
      new THREE.MeshStandardMaterial({ color: 0x0a0a0c, roughness: 0.5, metalness: 0.4 }));
    ejector.position.set(X + 0.026, -0.14, -0.55);
    g.add(ejector);

    // ---- 空仓挂机柄（套筒左侧凸起）----
    const slideStop = new THREE.Mesh(new THREE.BoxGeometry(0.014, 0.014, 0.03), uspDarkMat);
    slideStop.position.set(X - 0.026, -0.16, -0.46);
    g.add(slideStop);

    // ---- 导杆（套筒下方细圆柱，3D 卡通细节）----
    const guideRod = new THREE.Mesh(new THREE.CylinderGeometry(0.005, 0.005, 0.2, 6), uspDarkMat);
    guideRod.rotation.x = Math.PI / 2;
    guideRod.position.set(X, -0.16, -0.5);
    g.add(guideRod);

    // 枪口火光
    const flash = this._makeMuzzleFlashMesh(X, -0.145, -0.66);
    g.add(flash);
    g.userData.flash = flash;
    return g;
  }

  // AK-47 皮克斯风格 v3 重建（参考 jimeng 爆炸图 + 2089403292898562048 爆炸图 + mulan 三视图）
  // 写实比例 + 完整部件：复进簧组件、弹匣卡笋、握把防滑纹、枪托尾栓环
  // 枪托/护木/握把 ExtrudeGeometry 写实轮廓；机匣加复进簧+导杆
  // 弹匣一体弯曲月牙（不分段）；护木上下两片包裹；准星罩完整方框
  // 配色：木件同源浅色木（枪托/护木/握把同纹），机匣暖青铜军绿，弹匣黑色
  _buildAK(warmMat, woodMat, armyMat, darkMat) {
    const g = new THREE.Group();
    const X = 0.22;

    // ========== 机匣（修长写实比例 + 复进簧组件） ==========
    const recvBody = new THREE.Mesh(new THREE.BoxGeometry(0.060, 0.078, 0.36), warmMat);
    recvBody.position.set(X, -0.190, -0.54);
    g.add(recvBody);
    // 机匣盖（顶部隆起长条）
    const cover = new THREE.Mesh(new THREE.CylinderGeometry(0.026, 0.026, 0.30, 14), warmMat);
    cover.rotation.x = Math.PI / 2;
    cover.position.set(X, -0.150, -0.50);
    g.add(cover);
    // 复进簧组件（银色弹簧+导杆，从机匣后部伸出，参考图 1 编号 4）
    const springMat = new THREE.MeshPhysicalMaterial({ color: 0xb8b8b0, roughness: 0.35, metalness: 0.92, clearcoat: 0.3 });
    const springTube = new THREE.Mesh(new THREE.CylinderGeometry(0.013, 0.013, 0.16, 10), springMat);
    springTube.rotation.x = Math.PI / 2;
    springTube.position.set(X, -0.190, -0.30);
    g.add(springTube);
    for (let i = 0; i < 14; i++) {
      const ring = new THREE.Mesh(new THREE.TorusGeometry(0.014, 0.0015, 6, 12), springMat);
      ring.position.set(X, -0.190, -0.30 + (i - 7) * 0.011);
      ring.rotation.y = Math.PI / 2;
      g.add(ring);
    }
    const guide = new THREE.Mesh(new THREE.CylinderGeometry(0.005, 0.005, 0.20, 8), springMat);
    guide.rotation.x = Math.PI / 2;
    guide.position.set(X, -0.190, -0.30);
    g.add(guide);
    const guideCap = new THREE.Mesh(new THREE.SphereGeometry(0.008, 10, 8), springMat);
    guideCap.position.set(X, -0.190, -0.20);
    g.add(guideCap);
    // 机匣铆钉
    for (const [ry, rz] of [[-0.172, -0.45], [-0.172, -0.52], [-0.200, -0.59], [-0.172, -0.66], [-0.200, -0.48]]) {
      const rivet = new THREE.Mesh(new THREE.SphereGeometry(0.008, 10, 8), darkMat);
      rivet.position.set(X + 0.031, ry, rz);
      g.add(rivet);
    }
    const selector = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.018, 0.010, 14), darkMat);
    selector.rotation.z = Math.PI / 2;
    selector.position.set(X + 0.034, -0.175, -0.555);
    g.add(selector);
    const charging = new THREE.Mesh(new THREE.CylinderGeometry(0.008, 0.008, 0.032, 10), darkMat);
    charging.rotation.z = Math.PI / 2;
    charging.position.set(X + 0.040, -0.168, -0.46);
    g.add(charging);

    // ========== 枪管 + 导气管 ==========
    const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.018, 0.30, 12), warmMat);
    barrel.rotation.x = Math.PI / 2;
    barrel.position.set(X, -0.180, -0.93);
    g.add(barrel);
    const gasTube = new THREE.Mesh(new THREE.CylinderGeometry(0.011, 0.011, 0.20, 10), warmMat);
    gasTube.rotation.x = Math.PI / 2;
    gasTube.position.set(X, -0.140, -0.82);
    g.add(gasTube);
    const gasBlock = new THREE.Mesh(new THREE.BoxGeometry(0.048, 0.048, 0.052), warmMat);
    gasBlock.position.set(X, -0.168, -0.87);
    g.add(gasBlock);

    // ========== 完整方框准星罩 ==========
    const sgBase = new THREE.Mesh(new THREE.BoxGeometry(0.030, 0.022, 0.020), warmMat);
    sgBase.position.set(X, -0.158, -1.06);
    g.add(sgBase);
    const sgFront = new THREE.Mesh(new THREE.BoxGeometry(0.032, 0.042, 0.007), warmMat);
    sgFront.position.set(X, -0.130, -1.070);
    g.add(sgFront);
    const sgBack = new THREE.Mesh(new THREE.BoxGeometry(0.032, 0.042, 0.007), warmMat);
    sgBack.position.set(X, -0.130, -1.050);
    g.add(sgBack);
    const sgTop1 = new THREE.Mesh(new THREE.BoxGeometry(0.007, 0.007, 0.030), warmMat);
    sgTop1.position.set(X - 0.013, -0.106, -1.06);
    g.add(sgTop1);
    const sgTop2 = new THREE.Mesh(new THREE.BoxGeometry(0.007, 0.007, 0.030), warmMat);
    sgTop2.position.set(X + 0.013, -0.106, -1.06);
    g.add(sgTop2);
    const sgPost = new THREE.Mesh(new THREE.CylinderGeometry(0.004, 0.004, 0.032, 8), darkMat);
    sgPost.position.set(X, -0.124, -1.06);
    g.add(sgPost);

    // ========== 圆筒枪口 ==========
    const muzzle = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.020, 0.060, 12), warmMat);
    muzzle.rotation.x = Math.PI / 2;
    muzzle.position.set(X, -0.180, -1.08);
    g.add(muzzle);
    const muzzleRing = new THREE.Mesh(new THREE.CylinderGeometry(0.024, 0.024, 0.014, 12), darkMat);
    muzzleRing.rotation.x = Math.PI / 2;
    muzzleRing.position.set(X, -0.180, -1.11);
    g.add(muzzleRing);

    // ========== 照门 ==========
    const rearSight = new THREE.Mesh(new THREE.BoxGeometry(0.016, 0.028, 0.016), darkMat);
    rearSight.position.set(X, -0.140, -0.39);
    g.add(rearSight);

    // ========== 写实木护木（上下两片包裹枪管） ==========
    const hgTop = new THREE.Mesh(
      (() => { const s = new THREE.Shape(); const L = 0.115, H = 0.025, R = 0.014;
        s.moveTo(-L + R, -H); s.lineTo(L - R, -H);
        s.quadraticCurveTo(L, -H, L, -H + R);
        s.lineTo(L, H - R); s.quadraticCurveTo(L, H, L - R, H);
        s.lineTo(-L + R, H); s.quadraticCurveTo(-L, H, -L, H - R);
        s.lineTo(-L, -H + R); s.quadraticCurveTo(-L, -H, -L + R, -H);
        return new THREE.ExtrudeGeometry(s, { depth: 0.048, bevelEnabled: true, bevelThickness: 0.011, bevelSize: 0.011, bevelSegments: 3, curveSegments: 10 });
      })(),
      woodMat
    );
    hgTop.geometry.rotateY(-Math.PI / 2);
    hgTop.position.set(X + 0.030 + 0.011, -0.150, -0.75);
    g.add(hgTop);
    const hgBot = new THREE.Mesh(hgTop.geometry, woodMat);
    hgBot.position.set(X + 0.030 + 0.011, -0.216, -0.75);
    g.add(hgBot);
    const hgBandF = new THREE.Mesh(new THREE.CylinderGeometry(0.036, 0.036, 0.020, 12), warmMat);
    hgBandF.rotation.x = Math.PI / 2;
    hgBandF.position.set(X, -0.183, -0.67);
    g.add(hgBandF);
    const hgBandR = new THREE.Mesh(new THREE.CylinderGeometry(0.036, 0.036, 0.020, 12), warmMat);
    hgBandR.rotation.x = Math.PI / 2;
    hgBandR.position.set(X, -0.183, -0.84);
    g.add(hgBandR);
    const hgGroove = new THREE.Mesh(new THREE.BoxGeometry(0.007, 0.003, 0.180), darkMat);
    hgGroove.position.set(X, -0.121, -0.75);
    g.add(hgGroove);

    // ========== 写实木枪托（修长梯形 + 托腮 + 尾栓环） ==========
    const stShape = new THREE.Shape();
    stShape.moveTo(0, 0.012);
    stShape.lineTo(0.040, 0.022);
    stShape.lineTo(0.135, 0.018);
    stShape.quadraticCurveTo(0.195, 0.012, 0.200, -0.020);
    stShape.lineTo(0.198, -0.060);
    stShape.quadraticCurveTo(0.196, -0.092, 0.170, -0.092);
    stShape.lineTo(0.030, -0.080);
    stShape.quadraticCurveTo(0.000, -0.078, 0.000, -0.045);
    stShape.closePath();
    const stGeo = new THREE.ExtrudeGeometry(stShape, { depth: 0.046, bevelEnabled: true, bevelThickness: 0.010, bevelSize: 0.010, bevelSegments: 3, curveSegments: 12 });
    stGeo.rotateY(-Math.PI / 2);
    const stock = new THREE.Mesh(stGeo, woodMat);
    stock.position.set(X + 0.023 + 0.010, -0.190, -0.38);
    g.add(stock);
    // 枪托中部插接缝凹槽
    const stSeam = new THREE.Mesh(new THREE.BoxGeometry(0.004, 0.002, 0.110), darkMat);
    stSeam.position.set(X + 0.024, -0.192, -0.32);
    g.add(stSeam);
    // 橡胶托底（深色梯形包边）
    const buttPad = new THREE.Mesh(new THREE.BoxGeometry(0.054, 0.100, 0.020), darkMat);
    buttPad.position.set(X, -0.240, -0.183);
    buttPad.rotation.x = -0.10;
    g.add(buttPad);
    // 尾栓环（金属圈，参考图 1 枪托尾部下方）
    const slingRing = new THREE.Mesh(new THREE.TorusGeometry(0.008, 0.002, 6, 14), springMat);
    slingRing.position.set(X, -0.275, -0.190);
    slingRing.rotation.x = Math.PI / 2;
    g.add(slingRing);

    // ========== 手枪形木握把 + 防滑纹深色面板 ==========
    const grShape = new THREE.Shape();
    grShape.moveTo(-0.024, 0.012);
    grShape.lineTo(0.028, 0.005);
    grShape.quadraticCurveTo(0.034, -0.010, 0.040, -0.040);
    grShape.quadraticCurveTo(0.046, -0.075, 0.044, -0.105);
    grShape.quadraticCurveTo(0.042, -0.130, 0.026, -0.135);
    grShape.quadraticCurveTo(0.005, -0.138, -0.010, -0.130);
    grShape.quadraticCurveTo(-0.026, -0.115, -0.028, -0.080);
    grShape.quadraticCurveTo(-0.030, -0.040, -0.028, -0.010);
    grShape.quadraticCurveTo(-0.026, 0.012, -0.024, 0.012);
    const grGeo = new THREE.ExtrudeGeometry(grShape, { depth: 0.040, bevelEnabled: true, bevelThickness: 0.010, bevelSize: 0.010, bevelSegments: 3, curveSegments: 12 });
    grGeo.rotateY(-Math.PI / 2);
    const grip = new THREE.Mesh(grGeo, woodMat);
    grip.position.set(X + 0.020 + 0.010, -0.230, -0.40);
    g.add(grip);
    // 防滑纹深色面板（贴握把前侧，参考图 1 编号 9 密集圆点）
    const gripFace = new THREE.Mesh(
      (() => { const s = new THREE.Shape(); const L = 0.022, H = 0.10, R = 0.010;
        s.moveTo(-L + R, -H); s.lineTo(L - R, -H);
        s.quadraticCurveTo(L, -H, L, -H + R);
        s.lineTo(L, H - R); s.quadraticCurveTo(L, H, L - R, H);
        s.lineTo(-L + R, H); s.quadraticCurveTo(-L, H, -L, H - R);
        s.lineTo(-L, -H + R); s.quadraticCurveTo(-L, -H, -L + R, -H);
        return new THREE.ExtrudeGeometry(s, { depth: 0.003, bevelEnabled: false });
      })(),
      darkMat
    );
    gripFace.position.set(X - 0.001, -0.230, -0.45);
    g.add(gripFace);
    // 防滑纹点（密集深色小球覆盖握把前侧）
    for (let row = 0; row < 10; row++) {
      for (let col = 0; col < 4; col++) {
        const dot = new THREE.Mesh(new THREE.SphereGeometry(0.0022, 6, 4), darkMat);
        dot.position.set(X - 0.003, -0.185 - row * 0.011, -0.465 + col * 0.014);
        g.add(dot);
      }
    }

    // ========== 一体弯曲弹匣（ExtrudeGeometry 月牙形 + 4 条纵向棱） ==========
    const magShape = new THREE.Shape();
    magShape.moveTo(0, 0);
    magShape.lineTo(0, 0.025);
    magShape.quadraticCurveTo(0.030, 0.012, 0.090, -0.040);
    magShape.quadraticCurveTo(0.150, -0.110, 0.180, -0.150);
    magShape.lineTo(0.190, -0.130);
    magShape.quadraticCurveTo(0.180, -0.090, 0.150, -0.060);
    magShape.quadraticCurveTo(0.090, 0.000, 0.030, 0.020);
    magShape.quadraticCurveTo(0, 0.020, 0, 0);
    const magGeo = new THREE.ExtrudeGeometry(magShape, { depth: 0.040, bevelEnabled: true, bevelThickness: 0.005, bevelSize: 0.005, bevelSegments: 2, curveSegments: 16 });
    magGeo.rotateY(-Math.PI / 2);
    const mag = new THREE.Mesh(magGeo, armyMat);
    mag.position.set(X + 0.020 + 0.010, -0.215, -0.42);
    g.add(mag);
    // 4 条纵向凸棱（沿弹匣弧面铺设，参考图 11 弹匣棱纹）
    for (const off of [-0.022, -0.008, 0.008, 0.022]) {
      const ribShape = new THREE.Shape();
      ribShape.moveTo(0, -0.002);
      ribShape.lineTo(0, 0.020);
      ribShape.quadraticCurveTo(0.030, 0.010, 0.090, -0.035);
      ribShape.quadraticCurveTo(0.150, -0.100, 0.180, -0.140);
      ribShape.lineTo(0.178, -0.130);
      ribShape.quadraticCurveTo(0.150, -0.090, 0.090, -0.025);
      ribShape.quadraticCurveTo(0.030, 0.000, 0, -0.002);
      const ribGeo = new THREE.ExtrudeGeometry(ribShape, { depth: 0.003, bevelEnabled: false, curveSegments: 12 });
      ribGeo.rotateY(-Math.PI / 2);
      const rib = new THREE.Mesh(ribGeo, warmMat);
      rib.position.set(X - 0.005, -0.215, -0.42);
      rib.translateX(off);
      g.add(rib);
    }
    // 弹匣底板（梯形深色）
    const magFloor = new THREE.Mesh(new THREE.BoxGeometry(0.044, 0.018, 0.024), darkMat);
    magFloor.position.set(X, -0.340, -0.31);
    magFloor.rotation.x = -0.28;
    g.add(magFloor);
    // 弹匣卡笋
    const magCatch = new THREE.Mesh(new THREE.BoxGeometry(0.010, 0.020, 0.022), darkMat);
    magCatch.position.set(X, -0.220, -0.435);
    g.add(magCatch);

    // ========== 扳机 + 护圈 ==========
    const trigger = new THREE.Mesh(new THREE.BoxGeometry(0.010, 0.030, 0.010), darkMat);
    trigger.position.set(X, -0.240, -0.443);
    trigger.rotation.x = 0.15;
    g.add(trigger);
    const gFront = new THREE.Mesh(new THREE.BoxGeometry(0.004, 0.028, 0.004), darkMat);
    gFront.position.set(X, -0.245, -0.455);
    g.add(gFront);
    const gBack = new THREE.Mesh(new THREE.BoxGeometry(0.004, 0.028, 0.004), darkMat);
    gBack.position.set(X, -0.245, -0.421);
    g.add(gBack);
    const gBottom = new THREE.Mesh(new THREE.BoxGeometry(0.004, 0.004, 0.038), darkMat);
    gBottom.position.set(X, -0.258, -0.438);
    g.add(gBottom);

    // 枪口火光（对准新枪口末端）
    const flash = this._makeMuzzleFlashMesh(X, -0.180, -1.12);
    g.add(flash);
    g.userData.flash = flash;
    return g;
  }

  // AWP 狙击步枪（3D 卡通：栓动式机匣 + 长枪管 + 顶部瞄准镜 + 木枪托 + 短弹匣 + 脚架）
  // 切到 AWP 时 camera.fov 降到 45°，实现"放大镜"远程狙击观察
  _buildAwp(armyMat, woodMat, darkMat, darkDarkMat) {
    const g = new THREE.Group();
    const X = 0.22;

    // ---- 栓动机匣（BoxGeometry，长方形）----
    const body = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.08, 0.35), armyMat);
    body.position.set(X, -0.18, -0.62);
    body.castShadow = true;
    g.add(body);

    // 栓动把手（机匣右侧凸起的小球）
    const bolt = new THREE.Mesh(new THREE.SphereGeometry(0.018, 8, 6), darkMat);
    bolt.position.set(X + 0.034, -0.16, -0.58);
    g.add(bolt);

    // 弹底板（机匣后部）
    const buttPlate = new THREE.Mesh(new THREE.BoxGeometry(0.055, 0.085, 0.012), darkMat);
    buttPlate.position.set(X, -0.18, -0.44);
    g.add(buttPlate);

    // ---- 枪管（长细圆柱，旋转指 -Z）----
    const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.022, 0.022, 0.45, 10), armyMat);
    barrel.rotation.x = Math.PI / 2;
    barrel.position.set(X, -0.16, -0.95);
    barrel.castShadow = true;
    g.add(barrel);

    // 枪口制退器（枪管前端粗环）
    const muzzleBrake = new THREE.Mesh(new THREE.CylinderGeometry(0.028, 0.024, 0.04, 8), darkMat);
    muzzleBrake.rotation.x = Math.PI / 2;
    muzzleBrake.position.set(X, -0.16, -1.18);
    g.add(muzzleBrake);

    // 准星（枪口前端的方框）
    const frontSight = new THREE.Mesh(new THREE.BoxGeometry(0.012, 0.025, 0.012), darkMat);
    frontSight.position.set(X, -0.13, -0.72);
    g.add(frontSight);

    // ---- 瞄准镜（顶部显著圆柱 + 前后镜片 + 两个固定夹）----
    // 镜筒
    const scope = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 0.2, 12), darkDarkMat || darkMat);
    scope.rotation.x = Math.PI / 2;
    scope.position.set(X, -0.07, -0.5);
    scope.castShadow = true;
    g.add(scope);

    // 前镜片（物镜）
    const scopeFront = new THREE.Mesh(new THREE.CircleGeometry(0.03, 16), darkMat);
    scopeFront.position.set(X, -0.07, -0.4);
    scopeFront.rotation.y = Math.PI;
    g.add(scopeFront);

    // 后镜片（目镜）
    const scopeRear = new THREE.Mesh(new THREE.CircleGeometry(0.025, 16), darkMat);
    scopeRear.position.set(X, -0.07, -0.6);
    g.add(scopeRear);

    // 瞄准镜固定夹（2 个小方块连接镜筒到机匣）
    const mount1 = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.018, 0.018), darkMat);
    mount1.position.set(X, -0.12, -0.45);
    g.add(mount1);
    const mount2 = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.018, 0.018), darkMat);
    mount2.position.set(X, -0.12, -0.55);
    g.add(mount2);

    // 瞄准镜调焦旋钮（镜筒中段的小圆柱）
    const focusKnob = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.02, 8), darkMat);
    focusKnob.rotation.x = Math.PI / 2;
    focusKnob.position.set(X + 0.032, -0.07, -0.5);
    g.add(focusKnob);

    // ---- 短弹匣（5 发，AWP 经典）----
    const mag = new THREE.Mesh(new THREE.BoxGeometry(0.035, 0.1, 0.04), darkMat);
    mag.position.set(X, -0.28, -0.48);
    mag.rotation.x = 0.08;
    g.add(mag);

    // ---- 扳机 + 扳机护圈（3 段 U 形）----
    const trigger = new THREE.Mesh(new THREE.BoxGeometry(0.012, 0.032, 0.012), darkMat);
    trigger.position.set(X, -0.225, -0.515);
    g.add(trigger);
    const guardLeft = new THREE.Mesh(new THREE.BoxGeometry(0.005, 0.035, 0.005), darkMat);
    guardLeft.position.set(X - 0.014, -0.24, -0.5);
    g.add(guardLeft);
    const guardRight = guardLeft.clone();
    guardRight.position.x = X + 0.014;
    g.add(guardRight);
    const guardBottom = new THREE.Mesh(new THREE.BoxGeometry(0.023, 0.005, 0.005), darkMat);
    guardBottom.position.set(X, -0.258, -0.5);
    g.add(guardBottom);

    // ---- 木枪托（机匣后部，AWP 经典）----
    const stock = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.075, 0.22), woodMat);
    stock.position.set(X, -0.18, -0.22);
    stock.castShadow = true;
    g.add(stock);

    // 枪托底板（橡胶）
    const stockPad = new THREE.Mesh(new THREE.BoxGeometry(0.052, 0.08, 0.01), darkMat);
    stockPad.position.set(X, -0.18, -0.11);
    g.add(stockPad);

    // ---- 脚架（枪管下方两根细支柱，可展开）----
    const bipodLeg1 = new THREE.Mesh(new THREE.CylinderGeometry(0.004, 0.004, 0.12, 4), darkMat);
    bipodLeg1.position.set(X - 0.018, -0.22, -0.82);
    bipodLeg1.rotation.x = 0.15;
    g.add(bipodLeg1);
    const bipodLeg2 = bipodLeg1.clone();
    bipodLeg2.position.x = X + 0.018;
    g.add(bipodLeg2);

    // 枪口火光（对准 AWP 枪口末端，最远端）
    const flash = this._makeMuzzleFlashMesh(X, -0.16, -1.2);
    g.add(flash);
    g.userData.flash = flash;
    return g;
  }

  _spawnMuzzleFlash() {
    const gun = this._viewGuns && this._viewGuns[this.currentId];
    const flash = gun && gun.userData.flash;
    if (flash) {
      flash.material.opacity = 1;
      flash.scale.setScalar(0.8 + Math.random() * 0.6);
      flash.rotation.z = Math.random() * Math.PI;
    }
    this._muzzleTimer = 0.04;
    // 枪模后坐位移
    this._viewRecoil = 1;
  }

  _updateViewModel(dt) {
    const w = CONFIG.weapons[this.currentId];
    // 切换武器显隐（两把枪各自独立高精度枪模）
    if (this._viewGuns) {
      this._viewGuns.usp.visible = (this.currentId === 'usp');
      this._viewGuns.ak47.visible = (this.currentId === 'ak47');
    }

    // ---- 后坐力回弹：枪口向上挑（rotation.x 正值 = 前方枪口抬起）+ 轻微后缩 ----
    this._viewRecoil = Math.max(0, this._viewRecoil - dt * 8);
    const kick = this._viewRecoil;
    // 上挑角度随武器后坐力参数放大（峰值 ≈ 7°~9°，视觉明显上跳）
    const recoilPitch = kick * (0.09 + w.recoil.x * 3.2);
    const recoilPush = kick * 0.05;      // 轻微后缩

    // 走路晃动
    const bob = Math.sin(this.player.viewBob * 2) * 0.01;
    this._viewGroup.position.x = bob * 0.5;

    // 切枪动画（F5）：下放→上抬，叠加在姿态上
    const sw = this._updateSwitchAnim(dt) || { y: 0, r: 0 };

    this._viewGroup.position.y = -Math.abs(bob) * 0.5 + sw.y;
    this._viewGroup.position.z = recoilPush;

    // 换弹时枪下倾（与后坐上挑叠加，不再互相覆盖）
    let dip = 0;
    if (this.reloadTimer > 0) {
      const t = 1 - this.reloadTimer / w.reloadTime;
      dip = Math.sin(t * Math.PI) * 0.4;
    }
    this._viewGroup.rotation.x = recoilPitch + dip + sw.r;
  }

  // ---------- 弹道与弹孔 ----------
  _spawnTracer(from, to) {
    // 池化复用：避免每发子弹 new Geometry/Line（高频分配触发 GC 卡顿）
    let line = this._tracerPool && this._tracerPool.pop();
    if (!line) {
      const geo = new THREE.BufferGeometry().setFromPoints([from, to]);
      const mat = new THREE.LineBasicMaterial({
        color: 0xffee88, transparent: true, opacity: 0.8,
      });
      line = new THREE.Line(geo, mat);
      this._tracerPool = this._tracerPool || [];
    } else {
      line.geometry.setFromPoints([from, to]);
    }
    line.userData.life = 0.06;
    line.material.opacity = 0.8;
    line.visible = true;
    this.scene.add(line);
    this._tracers.push(line);
  }

  _updateTracers(dt) {
    for (let i = this._tracers.length - 1; i >= 0; i--) {
      const t = this._tracers[i];
      t.userData.life -= dt;
      t.material.opacity = Math.max(0, t.userData.life / 0.06) * 0.8;
      if (t.userData.life <= 0) {
        this.scene.remove(t);
        t.visible = false;
        this._tracerPool.push(t);   // 归还池中复用，不再 dispose
        this._tracers.splice(i, 1);
      }
    }
    for (let i = this._impacts.length - 1; i >= 0; i--) {
      const m = this._impacts[i];
      m.userData.life -= dt;
      if (m.userData.life <= 0) {
        this.scene.remove(m);
        this._impactPool.push(m);
        this._impacts.splice(i, 1);
      }
    }
    for (let i = this._hitSparks.length - 1; i >= 0; i--) {
      const s = this._hitSparks[i];
      s.userData.life -= dt;
      s.material.opacity = Math.max(0, s.userData.life / 0.12);
      if (s.userData.life <= 0) {
        this.scene.remove(s);
        s.visible = false;
        this._hitPool.push(s);
        this._hitSparks.splice(i, 1);
      }
    }
  }

  _buildImpactPool() {
    this._impactPool = [];
    const geo = new THREE.CircleGeometry(0.06, 8);
    const mat = new THREE.MeshBasicMaterial({
      color: 0x111111, transparent: true, opacity: 0.9, side: THREE.DoubleSide,
    });
    for (let i = 0; i < 30; i++) {
      const m = new THREE.Mesh(geo, mat.clone());
      m.visible = false;
      this.scene.add(m);
      this._impactPool.push(m);
    }
  }

  _spawnImpact(point, normal) {
    let m = this._impactPool.pop();
    if (!m) return;
    // 沿墙面外法线微偏移避免 Z-fighting；面朝向法线，精确贴合墙面
    m.position.copy(point).addScaledVector(normal, 0.01);
    m.lookAt(point.clone().add(normal));
    m.visible = true;
    m.material.opacity = 0.9;
    m.userData.life = 6;
    this.scene.add(m);
    this._impacts.push(m);
  }

  reset() {
    this.currentId = 'usp';
    this.state = this._freshState('usp');
    this._stash = {};
    this.firing = false;
    this.reloadTimer = 0;
    this.fireCooldown = 0;
    this._spreadCurrent = 0;
    this._semiPending = false;
    this.switching = false;
    this._switchAnim = 0;
    this.hud.updateWeapon(CONFIG.weapons.usp, this.state);
  }

  dispose() {
    window.removeEventListener('mousedown', this._onMouseDown);
    window.removeEventListener('mouseup', this._onMouseUp);
    window.removeEventListener('keydown', this._onKeyDown);
  }
}

// 经典脚本全局暴露（依赖顺序：config → three(UMD) → map → player → enemy → weapon → …）
window.WeaponSystem = WeaponSystem;
